                                  <div className="pg-subj-toggle">
                                    <Tooltip text={`Use 'With Answer Sheet' for ${s}`}>
                                      <button
                                        className={`pg-subj-toggle-btn${sd.fmt === 'with' ? ' active-fmt' : ''}`}
