                                    </Tooltip>
                                    <Tooltip text={`Use 'No Answer Sheet' for ${s}`}>
                                      <button
                                        className={`pg-subj-toggle-btn${sd.fmt === 'without' ? ' active-fmt' : ''}`}
                                        onClick={() => setSubjFmt(ci, si, 'without')}
                                      >
                                        <i className="fa-regular fa-file" style={{ fontSize: 9 }}></i> No Sheet
                                      </button>
                                    </Tooltip>
                                  </div>
                                </div> */}

