  /* ═══════════════════════════════════════════════════════════════════
    DELETE CONFIRMATION DIALOG
    ═══════════════════════════════════════════════════════════════════ */
  .pg-delete-overlay {
    position:fixed; inset:0;
    background:rgba(0,0,0,.45);
    backdrop-filter:blur(4px);
    z-index:9999;
    display:none;
    align-items:center; justify-content:center;
    padding:20px;
  }
  .pg-delete-overlay.open { display:flex; }
  .pg-delete-dialog {
    background:#fff;
    border-radius:20px;
    width:100%; max-width:420px;
    padding:32px 28px 24px;
    box-shadow:0 30px 80px rgba(0,0,0,.22), 0 8px 24px rgba(0,0,0,.1);
    animation:pgDelIn .3s cubic-bezier(.34,1.2,.64,1) both;
    display:flex; flex-direction:column; align-items:center; gap:0;
  }
  @keyframes pgDelIn {
    from { opacity:0; transform:scale(.88) translateY(18px); }
    to   { opacity:1; transform:none; }
  }
  .pg-del-icon-wrap { margin-bottom:18px; }
  .pg-del-icon-bg {
    width:64px; height:64px;
    border-radius:16px;
    background:#FEE2E2;
    display:flex; align-items:center; justify-content:center;
  }
  .pg-del-icon { font-size:26px; color:#DC2626; }
  .pg-del-title {
    font-size:19px; font-weight:800; color:#111827;
    text-align:center; margin-bottom:8px;
    font-family:inherit;
  }
  .pg-del-subtitle {
    font-size:13px; color:#6B7280;
    text-align:center; line-height:1.55;
    margin-bottom:18px;
    font-family:inherit;
  }
  .pg-del-subtitle strong { color:#374151; }
  .pg-del-detail-pill {
    width:100%;
    background:#F9FAFB;
    border:1.5px solid #E5E7EB;
    border-radius:10px;
    padding:12px 16px;
    font-size:13px; font-weight:600; color:#374151;
    text-align:center;
    margin-bottom:14px;
    letter-spacing:.01em;
  }
  .pg-del-warning {
    width:100%;
    background:#FEF2F2;
    border:1.5px solid #FECACA;
    border-radius:10px;
    padding:12px 14px;
    display:flex; align-items:flex-start; gap:10px;
    margin-bottom:24px;
  }
  .pg-del-warning span {
    font-size:12.5px; font-weight:500;
    color:#991B1B; line-height:1.5;
  }
  .pg-del-footer {
    display:flex; gap:12px; width:100%;
  }
  .pg-del-btn-cancel {
    flex:1; padding:13px;
    border:1.5px solid #D1D5DB;
    border-radius:12px;
    background:#fff; color:#374151;
    font-size:14px; font-weight:700;
    font-family:inherit;
    cursor:pointer; transition:all .15s;
  }
  .pg-del-btn-cancel:hover { background:#F9FAFB; border-color:#9CA3AF; }
  .pg-del-btn-confirm {
    flex:1; padding:13px;
    border:none; border-radius:12px;
    background:linear-gradient(135deg,#DC2626,#B91C1C);
    color:#fff;
    font-size:14px; font-weight:700;
    font-family:inherit;
    cursor:pointer;
    display:flex; align-items:center; justify-content:center; gap:7px;
    transition:all .15s;
    box-shadow:0 4px 14px rgba(220,38,38,.35);
  }
  .pg-del-btn-confirm:hover {
    background:linear-gradient(135deg,#B91C1C,#991B1B);
    transform:translateY(-1px);
    box-shadow:0 6px 18px rgba(220,38,38,.45);
  }

